import '../../../../../Core/Storage/Local/local_storage_keys.dart';import '../../../../../Core/Storage/Local/local_storage_service.dart';import '../entities/login_model.dart';import '../../../../../Core/Storage/Remote/api_endpoints.dart';import '../../../../../Core/Storage/Remote/api_service.dart';import '../entities/register_model.dart';import '../entities/user_data_model.dart';Future<UserDataModel> getUserDataByEmail(LoginModel loginModel) async {  final response = await DioHelper.postData(    data: loginModel.toMap(),    path: ApiEndpoints.loginUser,  );  if (response?.statusCode == 200) {    await LocalStorageService.setValue(      LocalStorageKeys.token,      response!.data['access_token'],    );  }  return UserDataModel.fromJson(response?.data["user"]);}Future<bool> createAccount(RegisterModel registerModel) async {  final response = await DioHelper.postData(    data:registerModel.toMap() ,    path: ApiEndpoints.registerUser,  );  return  response?.data["status"];}